/* ════════════════════════════════════════════════════════════════════════
   rapid-questions.js — بنك بنود مقياس البصمة السريع (Rapid Fingerprint)
   الملف الموحَّد النهائي — مصهور آليًّا من الدفعات السبع عشرة المعتمدة
   ────────────────────────────────────────────────────────────────────────
   البنية العليا للكائن:
     intros            : مقدمات المراحل (stageA/B/C/D/E/F)
     stageA            : بوابة العائلة — ٧ مواقف (مرآة الدوافع مضغوطة)
     stageB            : بوابة السلوك — ٧ مواقف (مرآة السلوك مضغوطة)
     stageC            : بنود التأكيد — ١٨ عبارة للمرايا الوسطى الثلاث
     duels             : بطاريات الحسم للأزواج الضيقة السبعة
                         (٣ مبارزات + بندا جذر + تعرّف مرآتي لكل زوج)
     recognitionVoices : بنك الأصوات القانونية الموحَّد — type1..type9
                         (بنود recognition تشير إليه بمفتاح type فقط؛
                          المحرك يقرأ نص الصوت من هذا البنك حصرًا)
     stageE            : كتلة المسارات — ٨ بنود + بندا ترتيب إجباري
     rankingItems      : بندا الترتيب الإجباري (يُقدَّمان عند closeTop)
     spectrum          : عبارات الطيف — ٩ طبائع × ٣ محاور × ٣ قوى × ٥ عبارات

   المرجعان الحاكمان: METHODOLOGY.md و LENSES.md في rapid-fingerprint/
   قاعدة الحساب البنيوية: القراءة بحقل category لا بالموضع.
   القاموس الأسود: المفاتيح الداخلية (type1.. / tamasuk..) للكود فقط —
   لا يُعرض للعميل رقم طابع ولا اسم طابع ولا اسم مرآة إطلاقًا.
   ════════════════════════════════════════════════════════════════════════ */

const RAPID_QUESTIONS = {

  intros: {},
  stageA: [],
  stageB: [],
  stageC: [],
  duels: {},
  recognitionVoices: {},
  stageE: [],
  rankingItems: [],
  spectrum: {}
};

/* ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓ [ batch-01-stageA.js ] ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓ */

/* ════════════════════════════════════════════════════════════════════════
   rapid-questions.js — الدفعة الأولى: بوابة العائلة (stageA)
   ────────────────────────────────────────────────────────────────────────
   المرحلة أ من المقياس السريع: تحديد عائلة الطابع من الثلاث.
   مفاتيح العائلات (داخلية — مطابقة لـ cross-config):
     agency    = الهمّة والعزيمة  {١، ٨، ٩}
     bonding   = الأنس والقرب     {٢، ٣، ٤}
     certainty = اليقين والبيان   {٥، ٦، ٧}

   قواعد البناء (من METHODOLOGY.md قسم ٥ + LENSES.md قسم ١):
     • كل بند موقف عمل ملموس، ثلاث استجابات تُقيَّم كلٌّ مستقلّةً ١..٧.
     • الاستجابة تصف القاسم المشترك للعائلة لا طابعًا بعينه داخلها.
     • نص فصيح + hint عاميّ (للسؤال ولكل استجابة) — نمط axes-questions حرفيًّا.
     • حقل lens يوثّق عدسة التمييز التي كُتب عليها البند (مرجعها LENSES.md).
     • توزيع العائلات على المواضع أ/ب/ج يتغيّر من بندٍ لبند (كسر انحياز الموضع).
     • البندان a2 وa7 زوج اتساق ناعم على عدسة واحدة بسطحين مختلفين —
       تباعُد إجابتيهما الشديد يخفض مؤشّر الثقة (يقرؤه المحرّك من consistencyPair).
   ════════════════════════════════════════════════════════════════════════ */


/* ─── مقدّمة المرحلة أ — تُعرَض قبل أول بند ─── */
RAPID_QUESTIONS.intros.stageA =
  "الأسئلة الجاية كلها مواقف من الشغل، وكل موقف تحته تلات ردود فعل. " +
  "قيّم كل واحدة لوحدها من ١ لـ ٧: واحد يعني «ده مش أنا خالص»، وسبعة يعني «ده أنا بالظبط». " +
  "مفيش قاعدة بتقول لازم واحدة تعلى والباقي يوطى — ممكن التلاتة ياخدوا درجات عالية، وممكن التلاتة يوطوا. " +
  "وأهم حاجة: السؤال دايمًا عن اللي بيحصل منك فعلًا، أوتوماتيك، قبل ما تفكّر — " +
  "مش اللي إنت شايف إنه الصح، ولا اللي بتحاول تعمله. " +
  "والتلات ردود في كل سؤال، التلاتة لناس محترمة وناجحة بتعيش بيهم — إحنا بنرسم خريطة، مش بنوزّع درجات.";

