/* ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓ [ batch-02-stageB.js ] ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓ */

/* ════════════════════════════════════════════════════════════════════════
   rapid-questions.js — الدفعة الثانية: بوابة السلوك (stageB)
   ────────────────────────────────────────────────────────────────────────
   المرحلة ب من المقياس السريع: تحديد أسلوب الحركة الأولى تحت الضغط.
   مفاتيح الأساليب (داخلية — مطابقة لهيكل النتيجة في METHODOLOGY):
     imtithal = الامتثال {١، ٢، ٦}  — انتظار إذنٍ من مرجعٍ قبل المبادرة
     hazm     = الحزم    {٣، ٧، ٨}  — المبادرة إلى ما لم يأتِ بعد
     insihab  = الانسحاب {٤، ٥، ٩}  — إخلاء الفضاء قبل أن يُسأل

   قواعد البناء (LENSES.md قسم ٢ — والفخاخ الثلاثة معالَجة بنيويًّا):
     • كل بند مؤطَّر على الثواني الأولى قبل التفكير، وكل المواقف مفاجئة
       بلا بروتوكول متعلَّم (علاج فخ السلوك الوظيفي المتعلَّم).
     • استجابات الامتثال تُكتَب ترقّبًا نشطًا متّصلًا بالموقف — الحركة مربوطة
       بإشارة، لا خفوتًا (علاج فخ قراءة تردد السادس انسحابًا).
     • استجابات الانسحاب تشمل صراحةً صورتيه: الانحسار الظاهر، والحضور
       الاجتماعي كامل العلامات مع غياب الجوهر (علاج فخ التاسع الموثَّق).
     • الاستجابة تصف القاسم المشترك للأسلوب لا طابعًا بعينه داخله.
     • نص فصيح + hint عاميّ، وتوزيع الأساليب على المواضع أ/ب/ج متغيّر.
     • البندان b2 وb5 زوج اتساق ناعم على عدسة مصدر الرخصة بسطحين مختلفين.

   ملاحظة تجميع: هذه الدفعة تُدمَج مع stageA في ملف rapid-questions.js الواحد
   عند اكتمال الدفعات — التصريح المستقل هنا لغرض الفحص فقط.
   ════════════════════════════════════════════════════════════════════════ */


/* ─── مقدّمة المرحلة ب — تُعرَض قبل أول بند ─── */
RAPID_QUESTIONS.intros.stageB =
  "الجزء ده مختلف شوية، فركّز معايا في حاجة واحدة. " +
  "الأسئلة الجاية مش عن رأيك ولا عن تصرّفك بعد ما تفكّر — دي عن اللي بيحصل منك في أول كام ثانية، " +
  "قبل ما عقلك يلحق يتدخّل. الجسم والعين والحركة الأولى. " +
  "في كل موقف، افتكر آخر مرة حصلك فيه حاجة شبهه، وشوف اللي طلع منك فعلًا وقتها — " +
  "مش اللي إنت متدرّب تعمله في شغلك، ولا اللي المفروض. " +
  "والتلات ردود، زي ما اتفقنا، التلاتة لناس محترمة — مفيش رد أحسن من رد.";

