  type1: "«الأسبوع ده تقيل... والشغل مش مظبوط زيّ ما لازم يكون — وده اللي مضايقني أكتر من التعب نفسه. فيه صوت جوّايا شغّال مراجعة من غير أجازة: ده مش صحّ، ده كان لازم يتعمل أحسن — عليّا أنا قبل أيّ حد. بحاول أريّح شويّة، ألاقي الصوت بيقول: مش وقته. الناس فاكراني قاسي عليهم... هم مش شايفين أنا قاسي على نفسي قدّ إيه. لو بس كلّ حاجة تستوي في مكانها الصحّ — ساعتها بقى أعرف أرتاح.»",

  type2: "«الأسبوع ده تقيل... بس فيه ناس محتاجاني ومش هقدر أقصّر معاهم. الغريبة إنّي بحسّ بتعب الناس قبل تعبي أنا — تعبي بييجي في الآخر، لمّا ألاقي إنّ محدّش فاضيلي. مش بطلب... بس نفسي حد يلاحظ من غير ما أقول. ولمّا حد يفتكرني بحاجة صغيّرة بجد، الدنيا بتنوّر عليّ. بس فيه سؤال بيكبر جوّايا في الهدوء: أنا اللي واقف جنب الكلّ... مين الواقف جنبي أنا؟»",

