  type6: "«الأسبوع ده تقيل... ودماغي مش بتقف — شغّالة سيناريوهات: لو حصل كذا نعمل إيه؟ ولو كذا؟ محضّر لكلّ احتمال، ومع ذلك مش مرتاح. بدوّر على حد أثق فيه أستند له... وأوّل ما أستند يجيني شكّ: هو فعلًا يستاهل؟ والغريبة إنّي ساعات في قلب الخطر بتصرّف بشجاعة أنا نفسي مش فاهم جاية منين. اللي نفسي فيه بجدّ: أرض ثابتة تحت رجليّا... طالعة من جوّايا أنا، مش من حد.»",

