/* ════════════════════════════════════════════════════════════════════════
   rapid-questions.js — الدفعة السادسة: بنود التأكيد العامة (stageC)
   ────────────────────────────────────────────────────────────────────────
   بنك عبارات المودويلات للمرايا الوسطى الثلاث — تُقيَّم كلٌّ منها ١..٧.

   منطق الاستخدام (METHODOLOGY قسم ٣ — المرحلة ج):
   بعد أن تفرز البوابتان مرشحًا ومنافسًا، يحدد المحرك التقسيمات التي
   يفترقان فيها من جدول التواقيع، ويقدّم عن كل جبهة عبارتين: عبارة
   مودويل المرشح + عبارة مودويل المنافس. التقييم الأعلى يصوّت لصاحبه،
   وتُجمَع الأصوات في مؤشر الثقة. توافقٌ → إعلان؛ تعارضٌ → المرحلة (د).

   قرار ملزم من سلّم الصلاحية (LENSES قسم ٣):
   التأكيد يغطي M2 (الانتباه) وM3 (المشاعر) وM4 (النموذج الإدراكي) فقط.
   M6 (المعتقدات) وM7 (الجروح) خارج التأكيد نهائيًّا — مكانهما الحصري
   بنود الجذر داخل بطاريات الحسم. وحيث ورد في المنهجية ذكر المعتقدات
   ضمن مصادر التأكيد، فالحاكم هو هذا السلّم لأنه اللاحق والمعتمَد.

   قواعد الكتابة الآمنة المطبقة (من السلّم نفسه):
     • M2 من الأثر: ما التُقط أولًا وما اكتُشف لاحقًا أنه فات — لا سؤالًا
       مباشرًا عن وجهة النظر.
     • M3 من البصمة الجسدية والزمنية: أين ظهر وكم بقي وماذا رأى الناس —
       لا تسمية شعورية يُطلَب من صاحبها وعيٌ هو المعطَّل عند بعض الطبائع.
     • M4 من الفعل الذهني الملموس: ماذا فعل العقل بالمعلومة في الدقيقة
       الأولى — لا وصفًا مجردًا لأسلوب تفكير.

   البنية: عبارتان لكل مودويل × ٩ مودويلات = ١٨ عبارة.
   مفاتيح المودويلات مطابقة لجدول التواقيع في rapid-config.
   ════════════════════════════════════════════════════════════════════════ */


/* ─── مقدّمة المرحلة ج ─── */
