/* ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓ [ batch-07-stageE.js ] ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓ */

/* ════════════════════════════════════════════════════════════════════════
   rapid-questions.js — الدفعة السابعة: كتلة المسارات (stageE)
   ────────────────────────────────────────────────────────────────────────
   الوراثة المضغوطة من نواة مقياس المحاور (three-axes/axes-questions.js):
   نفس الهندسة الثلاثية للإشارات — وهي غير قابلة للاختزال لأنها أساس
   التفريق بين الداعم والمدفون:
     action   (الفعل التلقائي)  : الإشارة الأساسية للهيمنة — ٤ بنود (من ٦)
     longing  (الاشتياق)        : كاشف الجذب بلا فعل → المدفون — بندان (من ٣)
     critique (النقد)           : الباب الخلفي للمدفون وكاسر التعادل — بندان

   منطق الحساب موروث كما هو: الترتيب بالفعل، النقد كاسر تعادل، فجوة
   الاشتياق مؤكِّد للمدفون (computeAxisRanking). وعند علم التقارب
   closeTop يقدّم المحرك بندَي الترتيب الإجباري (rankingItems) حتى
   ينحسم الترتيب الثلاثي — لا نتيجة مفتوحة (METHODOLOGY، المرحلة هـ).

   مفاتيح المحاور مطابقة لـ axes-config وهيكل النتيجة:
     tamasuk   = التماسك   (الأمان والاستقرار وصون الذات)
     hayawiyya = الحيويّة  (الحياة والاشتعال والتجدّد)
     intima    = الانتماء  (المكان والدور والصلة بين الناس)

   قواعد الصياغة: نمط axes-questions حرفيًّا — مواقف من الحياة والعمل معًا
   (المحاور طاقة حياةٍ كاملة لا طاقة مكتب)، نص فصيح + hint عاميّ، تقييم
   مستقل ١..٧ لكل استجابة، نبل متساوٍ، تدوير المواضع.
   ════════════════════════════════════════════════════════════════════════ */


/* ─── مقدّمة المرحلة هـ ─── */
RAPID_QUESTIONS.intros.stageE =
  "دلوقتي بنقيس حاجة مختلفة: مش إنت بتتصرف إزاي — طاقتك بتروح فين. " +
  "المواقف الجاية من الحياة كلها مش من الشغل بس، ونفس النظام: " +
  "قيّم كل استجابة لوحدها من ١ لـ ٧ على قد ما هي بتحصل منك فعلًا. " +
  "وخد بالك: في الأسئلة اللي بتسأل عن اللي «نفسك فيه»، جاوب بالاشتياق الحقيقي " +
  "حتى لو عمرك ما عملته — الاشتياق نفسه معلومة.";

