/* ════════════════════════════════════════════════════════════════════════
   rapid-questions.js — الدفعة الثانية عشرة: عبارات الطيف (stageF)
   الطابع الرابع «الهوية الحقيقية» — كاملًا (المحاور الثلاثة)
   ────────────────────────────────────────────────────────────────────────
   المصدر: جداول نقاط القوة — الطابع الرابع (الجوهر: الهوية الحقيقية |
   الشوق: التجلّي الأصيل | الفضيلة: العِفَّة).
     المحور الأول: المُقْدِم الصَّامِد   (tamasuk)   → الإقْدَام · المُكَابَدَة · التَّجَلُّد
     المحور الثاني: الحَسَّاس المُنْكَشِف (intima)    → النَّفَاذ · المُوَاسَاة · الانْكِشَاف
     المحور الثالث: الجَهُور العَمِيق   (hayawiyya) → الجَهْر · المُغَالَبَة · الوَجْد

   العمارة والقواعد: القالب المعتمد حرفيًّا — خمس عبارات لكل قوة
   (balance ×١ · excess a/b · deficit a/b)، الحساب بحقل category،
   اسم القوة لا يظهر في النص، الاتزان قوة حقيقية، الانزلاق كُلفة على
   أرض الكرامة (الحِقْد يُكتَب مرارةً واعيةً لا وصمة)، الزمن مثبَّت على
   الفترة الأخيرة.
   سياقات المحاور: الأول في المغامرة والمثابرة والصمود الشخصي، الثاني
   في العمق الاجتماعي والأصالة وسط الجماعة، الثالث في التعبير والتنافس
   والعمق العاطفي في الصلات الوثيقة.
   ════════════════════════════════════════════════════════════════════════ */


