/* ════════════════════════════════════════════════════════════════════════
   rapid-questions.js — عبارات الطيف (stageF)
   الطابع التاسع «السلام الداخلي» — كاملًا (المحاور الثلاثة) — خاتمة التسعة
   ────────────────────────────────────────────────────────────────────────
   المصدر: جداول نقاط القوة — الطابع التاسع (الجوهر: السلام الداخلي |
   الشوق: التناغم المُحيي | الفضيلة: الحِلم).
     المحور الأول: السَّكَن   (tamasuk)   → الإدْفاء · المُداومة · الرَّزانة
     المحور الثاني: الجامِع   (intima)    → الإيلاف · التَّكريس · السَّعَة
     المحور الثالث: الخِلّ    (hayawiyya) → الأُنْس · التقبُّل · الصِّلَة

   العمارة والقواعد: القالب المعتمد حرفيًّا — خمس عبارات لكل قوة
   (balance ×١ · excess a/b · deficit a/b)، الحساب بحقل category،
   اسم القوة لا يظهر في النص، الاتزان قوة حقيقية، الانزلاق كُلفة على
   أرض الكرامة، الزمن مثبَّت على الفترة الأخيرة، وعبارات التفريط على
   لحظة الوعي الخافتة لصاحبها.
   جرح الطابع (الذات التي تُخلي مقعدها — «وأنت، ماذا تريد؟» أصعب
   الأسئلة) مخيط في مواضعه: التخدير (المريح الصغير بدل اللازم الكبير)،
   الانمحاء، التماهي (الغضب المدفون المتأخر)، الطَّمر.
   محور «تُحيي/تُخدِّر» — عمود الطابع في الجداول — حاكم لعبارات
   الاتزان كلها: السلام الحي اليقظ لا السكون النائم.
   سياقات المحاور: الأول في البيت والإيقاع والراحة الجسدية، الثاني في
   الجماعة والجمع والخدمة، الثالث في الصلات الحميمة واحدًا لواحد.
   ════════════════════════════════════════════════════════════════════════ */


